import { readFileSync } from 'node:fs';
import { type ModelLabPhotoReading, sha256Hex } from '@follow-up-engine/llm';

/**
 * The demo story's sample media (synthetic, generated by
 * scripts/generate-order-agent-samples.py): a photo of María's lab report
 * and her voice reply in Spanish and English. The scripted readers know
 * them by sha256, so the story plays without a Meta key; with a key, Muse
 * Spark and Muse Voice read the very same files.
 */
const ASSETS = new URL('../../assets/order-agent/', import.meta.url);

export const SAMPLE_FILES = {
  labReport: { file: 'lab-report.jpg', contentType: 'image/jpeg' },
  voiceEs: { file: 'voice-note-es.wav', contentType: 'audio/wav' },
  voiceEn: { file: 'voice-note-en.wav', contentType: 'audio/wav' },
} as const;
export type SampleName = keyof typeof SAMPLE_FILES;

export function readSample(name: SampleName): Uint8Array {
  return new Uint8Array(readFileSync(new URL(SAMPLE_FILES[name].file, ASSETS)));
}

/** What the sample photo shows (scripts/generate-order-agent-samples.py). */
export const SAMPLE_LAB_READING: ModelLabPhotoReading = {
  isLabReport: true,
  reportDate: '2025-12-29',
  patientName: 'Maria Fernanda Rojas',
  tests: [
    {
      name: 'Hemoglobina glicosilada (HbA1c)',
      value: 8.4,
      unit: '%',
      referenceLow: 4.0,
      referenceHigh: 5.6,
    },
    { name: 'Glucosa en ayunas', value: 162, unit: 'mg/dL', referenceLow: 70, referenceHigh: 99 },
  ],
};

/** What the sample voice notes say. */
export const SAMPLE_TRANSCRIPTS = {
  voiceEs:
    'Hola, sí. Ya me hice el examen la semana pasada, pero el martes no puedo. ¿Hay otro día?',
  voiceEn:
    "Hi, yes. I already had the test last week, but I can't make it on Tuesday. Is there another day?",
} as const;

function safeHash(name: SampleName): string | undefined {
  try {
    return sha256Hex(readSample(name));
  } catch {
    return undefined;
  }
}

/** Scripted vision readings by sha256 of the image. */
export function scriptedPhotoReadings(): Record<string, ModelLabPhotoReading> {
  const hash = safeHash('labReport');
  return hash === undefined ? {} : { [hash]: SAMPLE_LAB_READING };
}

/** Scripted transcripts by sha256 of the audio. */
export function scriptedTranscripts(): Record<string, string> {
  const out: Record<string, string> = {};
  for (const name of ['voiceEs', 'voiceEn'] as const) {
    const hash = safeHash(name);
    if (hash !== undefined) out[hash] = SAMPLE_TRANSCRIPTS[name];
  }
  return out;
}
